example:
if exist config.ini (
  echo Configuracao encontrada
) else (
  echo Configuracao nao encontrada
)

set /A idade=16
if %idade% GEQ 18 (
  echo Maior de idade
) else (
  echo Menor de idade
)

setlocal enabledelayedexpansion
set total=0
for %%n in (1 2 3) do (
  set /A total+=%%n
  echo Total parcial: !total!
)

xcopy C:\Origem D:\Destino /E /I
if %ERRORLEVEL% NEQ 0 (
  echo Falha ao copiar arquivos! Codigo: %ERRORLEVEL%
  exit /b 1
)

if not exist config.ini (
  echo Arquivo de configuracao ausente!
  exit /b 1
)
echo Continuando execucao normal...

net session >nul 2>&1
if %ERRORLEVEL% NEQ 0 (
  echo Este script precisa ser executado como administrador!
  exit /b 1
)
